/**
 * Loads the precomputed local Mushaf page dataset.
 *
 * Each page is a small JSON file under `public/data/pages/{n}.json`
 * (generated by `scripts/fetch-pages.mjs`). Files are cached in memory and
 * concurrent requests for the same page share a single in-flight fetch.
 */
const BASE_URL = import.meta.env.BASE_URL || '/'
const DATA_ROOT = `${BASE_URL.replace(/\/+$/, '')}/data/pages`
const TOTAL_PAGES = 604

const cache = new Map()
const inFlight = new Map()

function pageUrl(page) {
  return `${DATA_ROOT}/${page}.json`
}

function normalizePage(page) {
  const n = Number(page)
  if (!Number.isInteger(n) || n < 1 || n > TOTAL_PAGES) {
    throw new Error(`Invalid page number: ${page}`)
  }
  return n
}

/**
 * Load one page from the local dataset.
 * @param {number} page 1..604
 * @returns {Promise<object>} the lean page object
 */
async function loadPage(page) {
  const n = normalizePage(page)

  if (cache.has(n)) return cache.get(n)
  if (inFlight.has(n)) return inFlight.get(n)

  const request = (async () => {
    const response = await fetch(pageUrl(n))
    if (!response.ok) {
      throw new Error(`Page ${n} data unavailable (HTTP ${response.status})`)
    }
    const data = await response.json()
    if (data?.page !== n || !Array.isArray(data.lines)) {
      throw new Error(`Page ${n} data is invalid`)
    }
    cache.set(n, data)
    return data
  })()

  inFlight.set(n, request)
  try {
    return await request
  } finally {
    inFlight.delete(n)
  }
}

/**
 * Best-effort warm-up of neighbouring pages. Never throws.
 * @param {number|number[]} pages
 */
async function preload(pages) {
  const list = Array.isArray(pages) ? pages : [pages]
  await Promise.allSettled(
    list.map(async (page) => {
      const n = Number(page)
      if (!Number.isInteger(n) || n < 1 || n > TOTAL_PAGES) return
      if (cache.has(n) || inFlight.has(n)) return
      try {
        await loadPage(n)
      } catch {
        // Preloading is opportunistic; ignore failures.
      }
    }),
  )
}

/** Return an already-loaded page, or null. */
function getCached(page) {
  const n = Number(page)
  return Number.isInteger(n) ? (cache.get(n) ?? null) : null
}

/** Drop the in-memory cache (useful for tests/HMR). */
function clearCache() {
  cache.clear()
}

export default { loadPage, preload, getCached, clearCache }
export { loadPage, preload, getCached, clearCache }
